NEO4J.ActorStats.loadAll:
MATCH (n:Actor)
CALL { WITH n OPTIONAL MATCH (n)-[:ACTED_IN]->(h2)-[:DIRECTED_BY]->(t2:Director) WITH n, t2, h2 ORDER BY h2.released IS NULL, h2.released ASC WITH collect(DISTINCT t2) AS s2 RETURN head([x2 IN s2 | {props: properties(x2), labels: labels(x2)}]) AS v2 }
RETURN {root: {props: properties(n), labels: labels(n)}, rels: {directors: [x1 IN reduce(acc = [], y IN [(n)-[:ACTED_IN]->()-[:DIRECTED_BY]->(t1:Director) | t1] | CASE WHEN y IN acc THEN acc ELSE acc + y END) | {props: properties(x1), labels: labels(x1)}], firstDirector: v2, movieCount: size([(n)-[:ACTED_IN]->(t3) | 1]), averageRating: CASE WHEN size([(n)-[:RATED]->(t4) WHERE t4.score IS NOT NULL | t4.score]) = 0 THEN null ELSE reduce(s = 0.0, v IN [(n)-[:RATED]->(t4) WHERE t4.score IS NOT NULL | t4.score] | s + v) / size([(n)-[:RATED]->(t4) WHERE t4.score IS NOT NULL | t4.score]) END, bestRating: reduce(m = null, v IN [(n)-[:RATED]->(t5) WHERE t5.score IS NOT NULL | t5.score] | CASE WHEN m IS NULL OR v > m THEN v ELSE m END)}} AS result

NEO4J.ActorWithMovies.loadAll.where:
