MATCH (n:Actor)
CALL { WITH n OPTIONAL MATCH (n)-[:ACTED_IN]->()-[:DIRECTED_BY]->(t1) RETURN collect(DISTINCT CASE WHEN t1:Director THEN {props: properties(t1), labels: labels(t1)} END) AS v1 }
CALL { WITH n OPTIONAL MATCH (n)-[:ACTED_IN]->(h2)-[:DIRECTED_BY]->(t2) WITH n, t2, h2 ORDER BY h2.released IS NULL, h2.released ASC RETURN head(collect(DISTINCT CASE WHEN t2:Director THEN {props: properties(t2), labels: labels(t2)} END)) AS v2 }
CALL { WITH n OPTIONAL MATCH (n)-[:ACTED_IN]->(t3) RETURN count(t3) AS v3 }
CALL { WITH n OPTIONAL MATCH (n)-[:RATED]->(t4) RETURN avg(t4.score) AS v4 }
CALL { WITH n OPTIONAL MATCH (n)-[:RATED]->(t5) RETURN max(t5.score) AS v5 }
